CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, keywords TEXT NOT NULL, media_id TEXT, enabled INTEGER NOT NULL DEFAULT 1, link TEXT NOT NULL DEFAULT '', public_replies TEXT NOT NULL DEFAULT '[]', flow TEXT NOT NULL DEFAULT '{}', fuzzy INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conversations (id INTEGER PRIMARY KEY AUTOINCREMENT, ig_user TEXT NOT NULL, rule_id INTEGER NOT NULL, step TEXT NOT NULL, tries INTEGER NOT NULL DEFAULT 0, email TEXT, username TEXT, comment_id TEXT, follow_asked_at INTEGER, started INTEGER NOT NULL, updated INTEGER NOT NULL, UNIQUE (ig_user, rule_id));
CREATE INDEX IF NOT EXISTS conversations_active ON conversations (step, updated);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, ig_user TEXT, username TEXT, comment_id TEXT, rule_id INTEGER, keyword TEXT, text TEXT, error TEXT);
CREATE INDEX IF NOT EXISTS events_ts ON events (ts DESC);
CREATE TABLE IF NOT EXISTS processed (key TEXT PRIMARY KEY, ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sends (ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sends_ts ON sends (ts);
CREATE TABLE IF NOT EXISTS outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, due INTEGER NOT NULL, job TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', error TEXT);
CREATE INDEX IF NOT EXISTS outbox_due ON outbox (status, due);
